import re

try:
    import tiktoken
except ImportError:
    tiktoken = None

_PATTERN = re.compile(r"\s?[A-Za-z]+|\s?\d+|\s?[^\sA-Za-z\d]+|\s+")


def _split_tokens(text, model):
    if tiktoken is not None:
        try:
            encoder = tiktoken.encoding_for_model(model)
            return [encoder.decode([t]) for t in encoder.encode(text)]
        except Exception:
            pass
    return _PATTERN.findall(text)


def analyze_tokens(text, model='gpt-4o'):
    tokens = _split_tokens(text, model)
    # token_count counts word tokens (punctuation-only tokens are excluded);
    # the cost is billed on every token.
    word_count = sum(1 for t in tokens if any(c.isalnum() for c in t))
    return {
        'token_count': word_count,
        'tokens': tokens,
        'estimated_cost': len(tokens) * 0.15 / 1_000_000,
    }


result = analyze_tokens('Python is the best programming language for AI development.')
print(f"Token count: {result['token_count']}")
print(f"Tokens: {result['tokens']}")
print(f"Estimated cost: ${result['estimated_cost']:.8f}")
